import { existsSync } from 'node:fs';

import { expect, test } from '../../fixtures/index.ts';

import { openInsights, tile } from './insights-helpers.ts';

// `@visual` baselines for the practice insights dashboard (#966): the owner's report, its
// preparedness data table, a junior's own view and the denied state, in the 360/768/1280 light and
// dark projects. Baselines are only generated by the e2e workflow's `update_snapshots` dispatch (see
// e2e/README.md); until they exist each test skips. The seeded hearings are relative to now, so the
// range line, the computed time and the weekly sparkline (its points depend on the weekday) are
// masked.
const STATES = ['owner', 'owner-table', 'junior', 'denied'] as const;

for (const name of STATES) {
  test(`insights ${name}`, { tag: '@visual' }, async ({ page, asUser, db }, testInfo) => {
    const file = `insights-${name}.png`;
    const baseline = testInfo.snapshotPath(file, { kind: 'screenshot' });
    test.skip(
      testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
      'no baseline yet: dispatch the e2e workflow with update_snapshots',
    );
    const role = name === 'junior' ? 'junior' : name === 'denied' ? 'clerk' : 'owner';
    await openInsights(page, asUser, db.name, { role });
    if (name === 'denied') {
      await expect(page.locator('main')).toHaveScreenshot(file);
      return;
    }
    const report = page.locator('main [data-slot="insights"]').filter({ visible: true });
    await expect(report).toBeVisible();
    if (name === 'owner-table') {
      await tile(page, 'Preparedness').getByRole('button', { name: 'Show chart and data' }).click();
      await page.keyboard.press('t');
      await expect(page.locator('[data-slot="insights-data-table"]').first()).toBeVisible();
    }
    await expect(report).toHaveScreenshot(file, {
      mask: [
        report.locator(':scope > p').first(),
        report.locator('[data-slot="insights-sparkline"]'),
        report.locator('[data-slot="insights-hero"] p.text-xs'),
        report.locator('[data-slot="insights-data-table"] tbody'),
        report.locator('[data-slot="insights-chart"]'),
      ],
    });
  });
}
